Complete local Rust example; the app itself does not execute it:
```rust

fn minutes(text: &str) -> Result<u32, &'static str> {
    let n = text.trim().parse::<u32>().map_err(|_| "invalid integer")?;
    if !(1..=60).contains(&n) { return Err("outside 1 through 60"); }
    Ok(n)
}
fn main() {
    match minutes(" 15 ") {
        Ok(value) => println!("{value}"),
        Err(message) => println!("{message}"),
    }
}
```

